/* Squad GK & G10 Arena. UI and game state; Firebase Auth owns credentials. */
(()=>{'use strict';
const KEY='squad-arena-v1', $=s=>document.querySelector(s), now=()=>Date.now();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const makeId=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36);
const blankLogs=()=>({signin:[],cheat:[],answers:[],questions:[],messages:[],admin:[]});
function fresh(){return{version:2,users:[],questions:Rules.seedQuestions.map(q=>({...q})),mode:'auto',chat:[],dms:[],notices:[],challenges:[],reports:[],supportRequests:[],adminAlerts:[],logs:blankLogs(),accepted:false,realitySeen:false,session:{awayEvents:[]}}}
function loadLocal(){try{let raw=JSON.parse(localStorage.getItem(KEY)||'null');if(!raw||typeof raw!=='object')return fresh();let x={...fresh(),...raw};for(const k of ['users','questions','chat','dms','notices','challenges','reports','supportRequests','adminAlerts'])if(!Array.isArray(x[k]))x[k]=[];x.logs={...blankLogs(),...(x.logs||{})};for(const k of Object.keys(x.logs))if(!Array.isArray(x.logs[k]))x.logs[k]=[];x.session=x.session&&typeof x.session==='object'?x.session:{awayEvents:[]};if(!Array.isArray(x.session.awayEvents))x.session.awayEvents=[];return x}catch{return fresh()}}
let state=loadLocal(), currentId=null, page='Home', quiz=null, selected=null, lastChat=0, awayAt=0, filter='all', logMode='summary', cloudStops=[], syncingRemote=false, alertOpen=false, pendingProfiles={};
const uid=()=>currentId, me=()=>state.users.find(x=>x.id===uid()), byId=id=>state.users.find(x=>x.id===id), isStaff=u=>u&&['admin','moderator'].includes(u.role);
function userDefaults(id,name,username){return{id,name:name||'Player',username:username||'player',role:'user',points:0,created:now(),answers:[],streak:0,bestStreak:0,daily:0,lastDay:'',hints:0,shields:1,freezes:1,titles:[],banned:false,suspended:false,mutedUntil:0,nameChanged:0}}
function safeLocal(){let copy={...state,users:state.users.map(u=>{let x={...u};delete x.password;delete x.passwordHash;delete x.passwordSalt;delete x.email;return x}),current:null};return copy}
function save(){try{localStorage.setItem(KEY,JSON.stringify(safeLocal()))}catch(e){toast('Could not save this device’s cache: '+e.message,'bad')}}
function cloud(){return window.ArenaFirebase?.ready?window.ArenaFirebase:null}
function write(path,value){let c=cloud();if(!c||!c.auth.currentUser)return Promise.reject(Error('Sign in to sync data.'));return c.write(path,value).catch(error=>{console.warn('Firebase write denied',path,error);toast('Cloud update failed: '+(error.code||error.message),'bad');throw error})}
function listen(path,fn){let c=cloud();if(!c)return()=>{};let off=c.listen(path,value=>{syncingRemote=true;try{fn(value);save();render()}finally{syncingRemote=false}},error=>{console.warn('Firebase listener denied',path,error);if(!window._arenaRulesToast){window._arenaRulesToast=true;toast('Firebase database rules need to be published before shared sync works.','bad')}});cloudStops.push(off);return off}
function stopCloud(){for(const off of cloudStops)try{off()}catch{}cloudStops=[]}
function toast(text,type='good'){let root=$('#toasts');if(!root)return;let node=document.createElement('div');node.className='toast '+type;node.textContent=text;root.append(node);setTimeout(()=>node.remove(),3600)}
function modal(html){$('#modal-root').innerHTML=`<div class="overlay"><section class="modal">${html}</section></div>`}
function closeModal(){$('#modal-root').innerHTML='';alertOpen=false}
function confirmAction(title,body,fn){modal(`<div class="eyebrow">Confirm action</div><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="row"><button data-action="confirm">Confirm</button><button class="secondary" data-action="close">Cancel</button></div>`);window._arenaConfirm=fn}
function twoStep(title,body,fn){confirmAction(title,body,()=>confirmAction('Confirm again',`This is a major Admin action: ${title}. Continue only if you intended it.`,fn))}
function log(type,data){if(!state.logs[type])state.logs[type]=[];let item={id:makeId(),at:now(),...data};state.logs[type].unshift(item);state.logs[type]=state.logs[type].slice(0,1200);save();if(uid()&&cloud()&&!syncingRemote)write(`logs/${uid()}/${type}/${item.id}`,item).catch(()=>{})}
function displayName(u){return esc(u?.name||'Unknown player')}
function roleBadge(u){return `<span class="badge ${esc(u?.role||'user')}">${esc(u?.role||'user')}</span>`}
function scoreOf(u){return Number(u?.points)||0}
function updateProfileCloud(u=me()){if(!u||!cloud()||syncingRemote)return Promise.resolve();return Promise.all([write(`profiles/${u.id}`,{displayName:u.name||'Player',username:u.username||'player',createdAt:u.created||now()}),write(`scores/${u.id}`,{points:scoreOf(u),streak:u.streak||0,bestStreak:u.bestStreak||0,accuracy:Rules.accuracy(u.answers||[])})]).catch(()=>{})}
function updatePrivateCloud(u=me()){if(!u||!cloud()||syncingRemote)return Promise.resolve();return write(`playerData/${u.id}`,{answers:u.answers||[],daily:u.daily||0,lastDay:u.lastDay||'',hints:u.hints||0,shields:u.shields||0,freezes:u.freezes||0,titles:u.titles||[]}).catch(()=>{})}
function profileFromCloud(id,p={}){let old=byId(id)||userDefaults(id);return{...old,id,name:p.displayName||old.name,username:p.username||old.username,created:p.createdAt||old.created}}
async function activate(fbUser){if(fbUser.isAnonymous){currentId=null;stopCloud();render();return}stopCloud();currentId=fbUser.uid;let profile=null,score=null,privateData=null,admin=false,mod=false,status=null;try{[profile,score,privateData,status,admin,mod]=await Promise.all([cloud().read(`profiles/${currentId}`),cloud().read(`scores/${currentId}`),cloud().read(`playerData/${currentId}`),cloud().read(`moderation/accounts/${currentId}`),cloud().read(`admins/${currentId}`),cloud().read(`moderators/${currentId}`)])}catch{}let u=byId(currentId)||userDefaults(currentId,pendingProfiles[currentId]?.name||fbUser.displayName||'Player',pendingProfiles[currentId]?.username||(fbUser.email||'player').split('@')[0].replace(/[^a-z0-9_]/gi,'').slice(0,20)||'player');if(profile){u.name=profile.displayName||u.name;u.username=profile.username||u.username;u.created=profile.createdAt||u.created}if(score)Object.assign(u,{points:Number(score.points)||0,streak:Number(score.streak)||0,bestStreak:Number(score.bestStreak)||0});if(privateData)Object.assign(u,privateData);u.role=admin===true?'admin':mod===true?'moderator':'user';u.banned=!!status?.banned;u.suspended=!!status?.suspended;if(!state.users.some(x=>x.id===u.id))state.users.push(u);currentId=u.id;state.session={started:now(),awaySeconds:0,awayEvents:[]};save();
listen('profiles',value=>{if(value)state.users=Object.entries(value).map(([id,p])=>profileFromCloud(id,p));if(!byId(currentId))state.users.push(u)});
listen('scores',value=>{for(const [id,s]of Object.entries(value||{})){let x=byId(id);if(x)Object.assign(x,{points:Number(s.points)||0,streak:Number(s.streak)||0,bestStreak:Number(s.bestStreak)||0})}});
listen(`playerData/${currentId}`,value=>{if(value){let x=me();if(x)Object.assign(x,value)}});
listen('chat',value=>{if(value)state.chat=Object.values(value).sort((a,b)=>(a.at||0)-(b.at||0)).slice(-150)});
listen(`dms/${currentId}`,value=>{if(value){let map=new Map(Object.values(value).map(x=>[x.id,x]));state.dms=[...map.values()].sort((a,b)=>(a.at||0)-(b.at||0))}});
listen('challenges',value=>{if(value)state.challenges=Object.values(value)});
listen('notices',value=>{if(value)state.notices=Object.values(value).sort((a,b)=>(b.at||0)-(a.at||0))});
listen('questions',value=>{if(value)state.questions=Object.values(value)});
listen('settings/mode',value=>{if(value)state.mode=value});
listen(`admins/${currentId}`,value=>{let x=me();if(x)x.role=value===true?'admin':x.role==='moderator'?'moderator':'user'});
listen(`moderators/${currentId}`,value=>{let x=me();if(x&&x.role!=='admin')x.role=value===true?'moderator':'user'});
listen(`moderation/accounts/${currentId}`,value=>{let x=me();if(x&&value)Object.assign(x,{banned:!!value.banned,suspended:!!value.suspended})});
listen(`supportRequests/${currentId}`,value=>{if(value)state.supportRequests=[...state.supportRequests.filter(x=>x.accountId!==currentId),...Object.values(value)]});
listen(`noticeReads/${currentId}`,value=>{for(const [noticeId,receipt]of Object.entries(value||{})){let n=state.notices.find(x=>x.id===noticeId);if(n){n.readBy=n.readBy||[];if(receipt.read&&!n.readBy.includes(currentId))n.readBy.push(currentId);n.acknowledgedBy=n.acknowledgedBy||[];if(receipt.acknowledged&&!n.acknowledgedBy.includes(currentId))n.acknowledgedBy.push(currentId)}}});
listen(`logs/${currentId}`,value=>{if(value)for(const [k,rows]of Object.entries(value))if(state.logs[k])state.logs[k]=Object.values(rows||{}).sort((a,b)=>(b.at||0)-(a.at||0))});
if(u.role==='admin'){listen('admins',value=>{for(const x of state.users)if(value?.[x.id])x.role='admin';else if(x.role==='admin')x.role='user'});listen('moderators',value=>{for(const x of state.users)if(x.role!=='admin')x.role=value?.[x.id]?'moderator':'user'});listen('moderation/accounts',value=>{for(const [id,s]of Object.entries(value||{})){let x=byId(id);if(x)Object.assign(x,{banned:!!s.banned,suspended:!!s.suspended})}});listen('supportRequests',value=>{if(value)state.supportRequests=Object.values(value).flatMap(rows=>Object.values(rows||{}))});listen('antiCheatAlerts',value=>{if(value)state.adminAlerts=Object.values(value).flatMap(rows=>Object.values(rows||{}));showAlerts()});listen('noticeReads',value=>{for(const [who,rows]of Object.entries(value||{}))for(const [noticeId,receipt]of Object.entries(rows||{})){let n=state.notices.find(x=>x.id===noticeId);if(n){n.readBy=n.readBy||[];if(receipt.read&&!n.readBy.includes(who))n.readBy.push(who);n.acknowledgedBy=n.acknowledgedBy||[];if(receipt.acknowledged&&!n.acknowledgedBy.includes(who))n.acknowledgedBy.push(who)}}});listen('logs',value=>{if(value){let logs=blankLogs();for(const groups of Object.values(value))for(const [k,rows]of Object.entries(groups||{}))if(logs[k])logs[k].push(...Object.values(rows||{}));for(const k of Object.keys(logs))logs[k].sort((a,b)=>(b.at||0)-(a.at||0));state.logs=logs}})}
if(!profile&&u.role!=='admin'&&!u.banned){await updateProfileCloud(u);await updatePrivateCloud(u)}page='Home';render();showAlerts()}
function showAlerts(){let u=me();if(!u||u.role!=='admin'||alertOpen)return;let a=state.adminAlerts.find(x=>!x.acknowledged);if(!a)return;alertOpen=true;modal(`<div class="eyebrow">Anti-cheat review</div><h2>Repeated away activity</h2><p><b>${esc(a.playerName||'Player')}</b> switched away ${a.count} times in about one minute.</p><p class="muted">This is a signal for review, not proof of cheating.</p><button data-action="ack-alert" data-id="${esc(a.id)}">Acknowledge</button>`)}
function badge(u){return `<span class="badge ${esc(u.role)}">${esc(u.role)}</span>`}
const navTabs=['Home','Play','Leaderboard','Challenges','Chat','Inbox','Profile','Policy'];
function render(){let u=me();if(!state.accepted){showPolicyGate();return}if(!state.realitySeen){modal(`<div class="eyebrow">Reality check</div><h2>Use a unique password</h2><p>Passwords are handled by Firebase Authentication. Admins can inspect private chats through moderation logs. Avoid sharing personal or sensitive information.</p><button data-action="reality">I understand</button>`);return}if(!u){renderAuth();return}if(u.banned||u.suspended){renderSuspended();return}$('#app').innerHTML=`<div class="shell"><header class="topbar"><div class="brand">⚡ Squad <span>GK & G10</span> Arena</div><div class="userbar"><div>${esc(u.name)} ${badge(u)} <span class="pill">${scoreOf(u)} pts</span></div><button class="secondary small" data-action="logout">Log out</button></div></header><nav class="nav">${navTabs.concat(isStaff(u)?['Questions','Logs']:[],u.role==='admin'?['Admin']:[]).map(t=>`<button class="secondary ${page===t?'active':''}" data-page="${t}">${t}</button>`).join('')}</nav><main>${pageContent(u)}</main><div class="footer">Squad GK & G10 Arena · <button class="secondary small" data-page="Policy">Privacy policy</button> · <span class="muted">Local cache + Firebase sync</span></div></div>`}
function showPolicyGate(){modal(`<div class="eyebrow">Before you enter</div><h2>Privacy policy</h2><div class="policy">${Rules.policies.map((p,i)=>`<h3>${i+1}. ${esc(p[0])}</h3><p>${esc(p[1])}</p>`).join('')}</div><p class="muted">Your acceptance is saved on this device.</p><button data-action="accept">Accept & Continue</button>`)}
function renderAuth(){page='Sign in';$('#app').innerHTML=`<div class="shell"><section class="hero"><div class="eyebrow">Welcome to the arena</div><h1>Squad GK & G10 Arena</h1><p>Quiz, build a streak, and challenge your squad.</p></section><div class="grid" style="margin-top:16px"><section class="card span6"><h2>Sign in</h2><form id="login" class="form"><label>Email<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button>Enter arena</button></form><button class="secondary" data-action="reset-email">Send password reset email</button><button class="secondary" data-action="help">Banned or locked out? Message Admin</button></section><section class="card span6"><h2>Create account</h2><form id="signup" class="form"><label>Display name<input name="name" maxlength="24" required></label><label>Username<input name="username" minlength="3" maxlength="20" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Password<input name="password" type="password" minlength="8" autocomplete="new-password" required></label><button>Create account</button></form></section><section class="card span12"><p class="muted">Use a unique password. The app no longer ships demo passwords or stores password hashes in its data.</p></section></div></div>`}
function renderSuspended(){let u=me();$('#app').innerHTML=`<div class="shell"><section class="card"><div class="eyebrow">Account access limited</div><h1>Contact the Admin</h1><p>Your account is banned or suspended. Send a support or appeal message below.</p><textarea id="appeal" maxlength="700" placeholder="Explain your appeal"></textarea><button data-action="appeal">Send appeal</button> <button class="secondary" data-action="logout">Log out</button></section></div>`}
function pageContent(u){switch(page){case'Home':return home(u);case'Play':return playPage(u);case'Leaderboard':return leaderboard();case'Challenges':return challenges(u);case'Chat':return chatPage(u);case'Inbox':return inbox(u);case'Profile':return profilePage(u);case'Policy':return policyPage();case'Questions':return questionAdmin(u);case'Logs':return logsPage(u);case'Admin':return adminPage(u);default:return home(u)}}
function today(){return new Date().toISOString().slice(0,10)}
function home(u){let mode=Rules.mode(today(),state.mode),round=Rules.makeRound(state.questions,mode,(u.answers||[]).map(a=>a.questionId));let n=state.notices[0];if(n){n.readBy=n.readBy||[];if(!n.readBy.includes(u.id)){n.readBy.push(u.id);write(`noticeReads/${u.id}/${n.id}`,{read:true}).catch(()=>{})}}let ack=n&&(n.acknowledgedBy||[]).includes(u.id);return `<section class="hero"><div class="eyebrow">${mode==='weekend'?'Weekend':'Weekday'} arena · ${today()}</div><h1>Ready for a quick brain sprint?</h1><p>${round.length} questions are available in today’s round.</p><button data-page="Play">${round.length?'Start today’s round':'Review the arena'}</button> <span class="pill">${Rules.rank(u.points)} · ${u.points} points</span></section><div class="grid" style="margin-top:14px"><section class="card span4"><div class="eyebrow">Your progress</div><div class="metric">${u.streak||0} 🔥</div><p>Current streak · best ${u.bestStreak||0} · daily ${u.daily||0}</p></section><section class="card span4"><div class="eyebrow">Daily rewards</div><h2>${u.shields||0} 🛡️ · ${u.freezes||0} ❄️</h2><p>Claim a daily bonus, shield, or streak freeze.</p><button class="secondary" data-action="daily">Claim daily reward</button></section><section class="card span4"><div class="eyebrow">Accuracy</div><div class="metric">${Rules.accuracy(u.answers||[])}%</div><p>${(u.answers||[]).length} answers · ${averageTime(u)}s average</p></section><section class="card span12"><div class="eyebrow">Arena notice</div>${n?`<div class="item notice"><div class="row between"><b>${esc(n.title)}</b><span class="pill">${n.readBy?.includes(u.id)?'Read':'Unread'}</span></div><p>${esc(n.body)}</p><div class="row"><span class="muted">${(n.readBy||[]).length} read · ${(n.acknowledgedBy||[]).length} acknowledged</span><button class="small" data-action="ack-notice" data-id="${esc(n.id)}" ${ack?'disabled':''}>${ack?'Acknowledged':'Acknowledge'}</button></div></div>`:'<p class="muted">No active notice.</p>'}</section></div>`}
function averageTime(u){let a=u.answers||[];return a.length?Math.round(a.reduce((s,x)=>s+(x.seconds||0),0)/a.length):0}
function startQuiz(){let u=me(),mode=Rules.mode(today(),state.mode),items=Rules.makeRound(state.questions,mode,(u.answers||[]).map(a=>a.questionId));if(!items.length){toast('No fresh questions are available right now.');return}quiz={items,index:0,started:now()};selected=null;page='Play';render()}
function playPage(u){if(!quiz)return `<section class="card"><div class="eyebrow">Daily quiz</div><h1>Play a round</h1><p>Weekday: 5 GK + 1 per subject. Weekend: 10 GK + 3 per subject.</p><button data-action="start-quiz">Start round</button><p class="muted">Question IDs lock after an answer, so each question awards points once.</p></section>`;let q=quiz.items[quiz.index];if(!q)return `<section class="card"><h1>Round complete 🎉</h1><p>Nice work. Your score and streak are saved.</p><button data-action="finish-quiz">Back to Home</button></section>`;let unlocked=Math.max(0,(q.releaseAt||0)-now());return `<section class="card"><div class="row between"><span class="pill">${esc(q.subject)}</span><span>${quiz.index+1} / ${quiz.items.length}</span><span class="timer" id="q-timer">${Rules.seconds(now()-quiz.started)}s</span></div><div class="progress"><i style="width:${Math.round(100*quiz.index/quiz.items.length)}%"></i></div><div class="question">${esc(q.text)}</div>${unlocked?`<p class="timer" data-unlock="${q.releaseAt}">Unlocking soon…</p>`:`<div class="answers">${q.options.map((x,i)=>`<button class="answer ${selected===i?'selected':''}" data-answer="${i}">${i+1}. ${esc(x)}</button>`).join('')}</div>`}<div class="row" style="margin-top:14px"><button data-action="submit-answer" ${selected==null||unlocked?'disabled':''}>Submit answer</button><button class="secondary" data-action="hint" ${u.points<5?'disabled':''}>Hint · 5 pts</button><button class="secondary" data-action="quit-quiz">Leave round</button></div></section>`}
function submitAnswer(){let u=me(),q=quiz?.items[quiz.index];if(!q||selected==null)return;if((u.answers||[]).some(x=>x.questionId===q.id)){toast('This question was already answered.','bad');quiz.index++;selected=null;render();return}let seconds=Rules.seconds(now()-quiz.started),correct=selected===q.answer,earned=correct?Rules.points(u.streak||0):0;u.answers=u.answers||[];u.answers.push({questionId:q.id,subject:q.subject,correct,seconds,at:now()});if(correct){u.streak=(u.streak||0)+1;u.bestStreak=Math.max(u.bestStreak||0,u.streak);u.points=(u.points||0)+earned;if(u.doubleNext){u.points+=earned;u.doubleNext=false}}else{u.streak=0;if(u.shields>0){u.shields--;u.streak=1}}log('answers',{player:u.id,playerName:u.name,questionId:q.id,subject:q.subject,correct,seconds,earned});quiz.index++;quiz.started=now();selected=null;awardTitles(u);save();updateProfileCloud(u);updatePrivateCloud(u);toast(correct?`Correct! +${earned} points`:'Answer recorded. Keep going.',correct?'good':'bad');render()}
function awardTitles(u){let a=u.answers||[];if(a.length>=3&&Rules.accuracy(a)>=60&&!u.titles.includes('Best Accuracy'))u.titles.push('Best Accuracy');if(a.length>=3&&Rules.accuracy(a)>=50&&!u.titles.includes('Fastest Timing'))u.titles.push('Fastest Timing');if(u.bestStreak>=5&&!u.titles.includes('Best Streak'))u.titles.push('Best Streak');for(const s of Rules.subjects)if(a.filter(x=>x.subject===s).length>=3&&!u.titles.includes(s+' Leader'))u.titles.push(s+' Leader')}
function hint(){let u=me(),q=quiz?.items[quiz.index];if(!q||u.points<5)return toast('You need at least 5 points for a hint.','bad');u.points-=5;save();updateProfileCloud(u);modal(`<div class="eyebrow">Hint · 5 points</div><h2>${esc(q.subject)}</h2><p>${esc(q.explanation||'Think about the key clue in the question.')}</p><button data-action="close">Back to question</button>`)}
function leaderboard(){let rows=state.users.filter(u=>!u.banned).sort((a,b)=>scoreOf(b)-scoreOf(a));return `<section class="card"><div class="eyebrow">Squad standings</div><h1>Leaderboard</h1><div class="list">${rows.map((u,i)=>`<div class="item leader-row"><span class="ranknum">${i+1}</span><div><button class="secondary small" data-action="profile" data-id="${esc(u.id)}">${esc(u.name)}</button> ${roleBadge(u)}<div class="muted">${Rules.rank(scoreOf(u))} · ${Rules.accuracy(u.answers||[])}% accuracy</div></div><b>${scoreOf(u)} pts</b></div>`).join('')||'<p class="muted">No players yet. Invite your squad.</p>'}</div></section>`}
function profilePage(u){return `<section class="card"><div class="profile-head"><div class="avatar">${esc((u.name||'?').slice(0,1).toUpperCase())}</div><div><h1>${esc(u.name)} ${roleBadge(u)}</h1><p class="muted">@${esc(u.username)} · ${Rules.rank(scoreOf(u))}</p></div></div><div class="grid" style="margin-top:14px"><div class="item span4"><b>${scoreOf(u)} pts</b><p>Points</p></div><div class="item span4"><b>${u.streak||0} 🔥</b><p>Current / best streak ${u.bestStreak||0}</p></div><div class="item span4"><b>${Rules.accuracy(u.answers||[])}%</b><p>Overall accuracy</p></div><div class="item span12"><b>Titles</b><p>${(u.titles||[]).map(esc).join(' · ')||'No titles yet'}</p></div></div><hr><h2>Account settings</h2><div class="row"><input id="new-name" placeholder="New display name"><button data-action="rename">Change name</button><button class="danger" data-action="delete-self">Delete my account</button></div><p class="muted">Names have a 5-day cooldown. Use Firebase email reset for password recovery.</p></section>`}
function profileModal(id){let u=byId(id);if(!u)return;modal(`<div class="profile-head"><div class="avatar">${esc((u.name||'?').slice(0,1).toUpperCase())}</div><div><h2>${esc(u.name)}</h2><p>@${esc(u.username)} · ${roleBadge(u)}</p></div></div><div class="item">${scoreOf(u)} points · ${Rules.accuracy(u.answers||[])}% accuracy · streak ${u.streak||0}</div><p>Titles: ${(u.titles||[]).map(esc).join(' · ')||'None yet'}</p>${id!==uid()?`<button data-action="start-dm" data-id="${esc(id)}">Message</button>`:''} <button class="secondary" data-action="close">Close</button>`)}
function challenges(u){let mine=state.challenges.filter(c=>c.from===u.id||c.to===u.id);let players=state.users.filter(x=>x.id!==u.id&&!x.banned&&!x.suspended);return `<section class="card"><div class="eyebrow">Head-to-head</div><h1>1v1 Challenges</h1><div class="row"><select id="challenge-target">${players.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} (@${esc(x.username)})</option>`).join('')}</select><button data-action="challenge">Send challenge</button></div><div class="list" style="margin-top:14px">${mine.map(c=>`<div class="item"><b>${esc(byId(c.from)?.name||'Player')} vs ${esc(byId(c.to)?.name||'Player')}</b><p>Status: ${esc(c.status)} ${c.result?`· ${esc(c.result)}`:''}</p>${c.to===u.id&&c.status==='pending'?`<button class="small" data-action="accept" data-id="${esc(c.id)}">Accept</button> <button class="small danger" data-action="decline" data-id="${esc(c.id)}">Decline</button>`:''}${c.status==='accepted'?`<button class="small" data-action="duel" data-id="${esc(c.id)}">Answer duel question</button>`:''}</div>`).join('')||'<p class="muted">No challenges yet.</p>'}</div></section>`}
function chatPage(u){return `<section class="card"><div class="eyebrow">Live chat · 5-second cooldown</div><h1>Arena chat</h1><div class="chatbox" id="chatbox">${state.chat.slice(-100).map(m=>`<div class="bubble ${m.from===u.id?'mine':''}"><button class="secondary small" data-action="profile" data-id="${esc(m.from)}">${esc(byId(m.from)?.name||m.username||'Player')}</button> <small>${new Date(m.at).toLocaleTimeString()}</small>${esc(m.text)}</div>`).join('')||'<p class="muted">Say hello to the squad.</p>'}</div><div class="row"><input id="chat-input" maxlength="300" placeholder="Message the squad"><button data-action="send-chat">Send</button></div></section>`}
function inbox(u){let people=state.users.filter(x=>x.id!==u.id),target=window.dmTarget||people[0]?.id,messages=state.dms.filter(m=>(m.from===u.id&&m.to===target)||(m.from===target&&m.to===u.id));return `<section class="card"><div class="eyebrow">Personal chat</div><h1>Inbox</h1><div class="row"><select id="dm-target">${people.map(x=>`<option value="${esc(x.id)}" ${x.id===target?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="chatbox" id="chatbox">${messages.map(m=>`<div class="bubble ${m.from===u.id?'mine':''}"><small>${m.from===u.id?'You':esc(byId(m.from)?.name||'Player')} · ${new Date(m.at).toLocaleTimeString()}</small>${esc(m.text)}${m.to===u.id&&!m.read?'<span class="receipt"> · Unread</span>':''}</div>`).join('')||'<p class="muted">No messages in this conversation.</p>'}</div><div class="row"><input id="dm-input" maxlength="500" placeholder="Private message"><button data-action="send-dm" data-id="${esc(target||'')}">Send</button></div><p class="muted">Admins can review messages when investigating reports.</p></section>`}
function questionAdmin(u){if(!isStaff(u))return '<section class="card"><h1>Staff access required</h1></section>';return `<section class="card"><div class="eyebrow">Question desk</div><h1>Questions</h1>${u.role==='admin'||u.role==='moderator'?`<form id="question-form" class="form"><label>Subject<select name="subject">${Rules.subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Question<input name="text" required maxlength="280"></label><label>Options (one per line)<textarea name="options" required></textarea></label><label>Correct option (1–4)<input name="answer" type="number" min="1" max="4" value="1"></label><label>Unlock time<input name="releaseAt" type="datetime-local"></label><button>Add question</button></form>`:''}<div class="list" style="margin-top:14px">${state.questions.map(q=>`<div class="item"><b>${esc(q.subject)}</b> · ${esc(q.text)} <span class="muted">${q.active?'Active':'Stopped'}</span> ${q.releaseAt>now()?`<span class="timer" data-unlock="${q.releaseAt}">Scheduled</span>`:''}<div class="row"><button class="small secondary" data-action="preview" data-id="${esc(q.id)}">Early preview</button>${u.role==='admin'||u.role==='moderator'?`<button class="small secondary" data-action="toggle-question" data-id="${esc(q.id)}">${q.active?'Stop':'Resume'}</button><button class="small danger" data-action="remove-question" data-id="${esc(q.id)}">Remove</button><button class="small secondary" data-action="schedule-question" data-id="${esc(q.id)}" data-add="900000">+15m</button><button class="small secondary" data-action="schedule-question" data-id="${esc(q.id)}" data-add="3600000">+1h</button><button class="small secondary" data-action="schedule-question" data-id="${esc(q.id)}" data-add="86400000">+24h</button>`:''}</div></div>`).join('')}</div></section>`}
function adminPage(u){if(u.role!=='admin')return '<section class="card"><h1>Admin access required</h1></section>';return `<section class="card"><div class="eyebrow">Top boss controls</div><h1>Admin control room</h1><div class="grid"><div class="span6 item"><h3>Day mode</h3><select id="day-mode"><option value="auto" ${state.mode==='auto'?'selected':''}>Auto</option><option value="weekday" ${state.mode==='weekday'?'selected':''}>Force Weekday</option><option value="weekend" ${state.mode==='weekend'?'selected':''}>Force Weekend</option></select><button data-action="save-mode">Save mode</button></div><div class="span6 item"><h3>Admin notice</h3><input id="notice-title" placeholder="Notice title"><textarea id="notice-body" placeholder="Message the squad"></textarea><button data-action="publish-notice">Publish notice</button></div><div class="span12 item"><h3>Accounts</h3><div class="scroll"><table class="table"><thead><tr><th>Player</th><th>Points</th><th>Role</th><th>Controls</th></tr></thead><tbody>${state.users.map(x=>`<tr><td>${esc(x.name)} <small>@${esc(x.username)}</small></td><td>${scoreOf(x)}</td><td><select id="role-${esc(x.id)}"><option ${x.role==='user'?'selected':''}>user</option><option ${x.role==='moderator'?'selected':''}>moderator</option><option ${x.role==='admin'?'selected':''}>admin</option></select></td><td><button class="small" data-action="role" data-id="${esc(x.id)}">Change role</button> <button class="small ${x.banned?'secondary':'danger'}" data-action="ban" data-id="${esc(x.id)}">${x.banned?'Unban':'Ban'}</button> <button class="small secondary" data-action="suspend" data-id="${esc(x.id)}">${x.suspended?'Unsuspend':'Suspend'}</button> <button class="small danger" data-action="remove-account" data-id="${esc(x.id)}">Remove arena data</button></td></tr>`).join('')}</tbody></table></div></div><div class="span6 item"><h3>Board tools</h3><button class="danger" data-action="reset-board">Reset leaderboard</button><button class="secondary" data-action="clear-logs">Clear logs</button><button class="secondary" data-action="export-backup">Export backup</button><button class="secondary" data-action="import-backup">Restore backup</button><input class="hidden" id="backup-file" type="file" accept="application/json"></div><div class="span6 item"><h3>Account help</h3>${supportInbox()}</div></div></section>`}
function supportInbox(){let open=state.supportRequests.filter(x=>x.status!=='resolved');return `<p>${open.length} open request(s)</p><div class="list">${open.slice(0,20).map(r=>`<div class="item"><b>${esc(r.username||'Player')} · ${esc(r.reason||'Help')}</b><p>${esc(r.message)}</p><button class="small" data-action="resolve-help" data-id="${esc(r.id)}" data-owner="${esc(r.userId||r.accountId)}">Mark resolved</button></div>`).join('')||'<p class="muted">No open requests.</p>'}</div>`}
const logNames={signin:'Sign-In / Login',cheat:'Anti-Cheat',answers:'Question Answered',questions:'Added & Removed Question',messages:'Messages & Legal Notice',admin:'Actions Done by Admin'};
function logsPage(u){if(!isStaff(u))return '<section class="card"><h1>Staff access required</h1></section>';let rows=Object.entries(state.logs).filter(([k])=>filter==='all'||filter===k).flatMap(([k,a])=>a.map(x=>({stream:k,...x}))).sort((a,b)=>(b.at||0)-(a.at||0));let show=logMode==='summary'?rows.slice(0,80):rows.slice(0,400);return `<section class="card"><div class="row between"><div><div class="eyebrow">Searchable audit trail</div><h1>Activity logs</h1></div><button class="secondary" data-action="export-logs">Export CSV</button></div><div class="row">${['summary','full'].map(x=>`<button class="secondary ${logMode===x?'active':''}" data-action="logs-mode" data-mode="${x}">${x==='summary'?'Summary log':'Full log'}</button>`).join('')}<select id="log-filter"><option value="all">All streams</option>${Object.keys(logNames).map(k=>`<option value="${k}" ${filter===k?'selected':''}>${esc(logNames[k])}</option>`).join('')}</select><input id="log-search" placeholder="Search log text"></div><div class="list" id="log-list">${show.map(x=>`<div class="item log-entry"><span class="pill">${esc(logNames[x.stream]||x.stream)}</span> <span class="muted">${new Date(x.at||now()).toLocaleString()}</span><b>${esc(logSummary(x))}</b>${logMode==='full'?`<details><summary>Details</summary><pre>${esc(JSON.stringify(x,null,2))}</pre></details>`:''}</div>`).join('')||'<p class="muted">No log events match.</p>'}</div></section>`}
function logSummary(x){return x.event||x.kind||x.action||`${x.player||''} ${x.questionId||''} ${x.correct===undefined?'':x.correct?'correct':'wrong'}`}
function policyPage(){return `<section class="card"><div class="eyebrow">Arena rules</div><h1>Privacy policy</h1>${Rules.policies.map((p,i)=>`<h3>${i+1}. ${esc(p[0])}</h3><p>${esc(p[1])}</p>`).join('')}<button data-action="policy-accept">I reread the policy</button></section>`}
function sendChat(){let u=me(),text=$('#chat-input')?.value.trim();if(!text)return;if(u.mutedUntil>now())return toast('Chat is temporarily unavailable.','bad');if(now()-lastChat<5000)return toast('Please wait 5 seconds between messages.','bad');let item={id:makeId(),from:u.id,username:u.username,text:text.slice(0,300),at:now()};state.chat.push(item);lastChat=now();log('messages',{kind:'live chat',from:u.id,text:item.text});save();write('chat/'+item.id,item).catch(()=>{});render()}
function sendDm(to){let u=me(),text=$('#dm-input')?.value.trim();if(!text||!to)return;let item={id:makeId(),from:u.id,to,text:text.slice(0,500),at:now(),read:false};state.dms.push(item);log('messages',{kind:'personal chat',from:u.id,to,text:item.text});save();Promise.all([write(`dms/${u.id}/${item.id}`,item),write(`dms/${to}/${item.id}`,item)]).catch(()=>{});render()}
function startDuel(id){let c=state.challenges.find(x=>x.id===id),q=state.questions.find(x=>x.active&&(x.releaseAt||0)<=now());if(!c||!q)return toast('No released question is ready.','bad');let choice=prompt(`${q.subject}: ${q.text}\n${q.options.map((x,i)=>`${i+1}. ${x}`).join('\n')}\nEnter 1–${q.options.length}`);let n=Number(choice)-1;if(n<0||n>=q.options.length)return;let r={player:uid(),questionId:q.id,correct:n===q.answer,at:now()};c.answers=c.answers||[];c.answers.push(r);let ans=c.answers.filter(x=>x.player===c.from||x.player===c.to);if(ans.length>=2){let points={};for(const x of ans)points[x.player]=(points[x.player]||0)+(x.correct?1:0);c.result=`${byId(c.from)?.name||'Player'} ${points[c.from]||0} – ${points[c.to]||0} ${byId(c.to)?.name||'Player'}`;c.status='complete'}save();write('challenges/'+c.id,c).catch(()=>{});toast(r.correct?'Correct duel answer!':'Duel answer recorded.');render()}
function syncRoleAdmin(targetId,role){let root=cloud()?.database?.ref();if(!root)return;let changes={};changes[`admins/${targetId}`]=role==='admin'?true:null;changes[`moderators/${targetId}`]=role==='moderator'?true:null;root.update(changes).catch(e=>toast(e.message,'bad'))}
function clearLogs(){state.logs=blankLogs();save();if(me()?.role==='admin')write('logs',null).catch(()=>{});else if(uid())write(`logs/${uid()}`,null).catch(()=>{});toast('Logs cleared.')}
function exportLogs(){let rows=['stream,time,summary,details'];for(const [k,a]of Object.entries(state.logs))for(const x of a)rows.push([logNames[k],new Date(x.at||now()).toISOString(),logSummary(x),JSON.stringify(x)].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','));download(new Blob([rows.join('\n')],{type:'text/csv'}),'squad-arena-logs.csv')}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backup(){let data={...safeLocal(),users:state.users.map(u=>({...u}))};download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'squad-arena-backup.json')}
function importBackup(file){file.text().then(raw=>{let x=JSON.parse(raw);if(!x||!Array.isArray(x.questions)||!Array.isArray(x.users)||!x.logs)throw Error('Backup format is not recognized.');confirmAction('Restore local backup','This replaces this device’s cached data.',()=>{state={...fresh(),...x,current:null};save();render();toast('Local backup restored.')})}).catch(e=>toast('Backup could not be read: '+e.message,'bad'))}
function markAway(){if(!me()||awayAt)return;awayAt=now();log('cheat',{event:'tab/window left',player:uid(),playerName:me().name,at:awayAt})}
function markReturn(){let u=me();if(!u||!awayAt)return;let t=now(),seconds=Rules.seconds(t-awayAt);awayAt=0;state.session.awaySeconds=(state.session.awaySeconds||0)+seconds;state.session.awayEvents=(state.session.awayEvents||[]).filter(x=>t-x<60000);state.session.awayEvents.push(t);let count=state.session.awayEvents.length;log('cheat',{event:'returned to arena',player:u.id,playerName:u.name,awaySeconds:seconds,totalAwaySeconds:state.session.awaySeconds,returnsInLastMinute:count,at:t});if(count>=3&&(!state.session.lastAwayAlertAt||t-state.session.lastAwayAlertAt>300000)){state.session.lastAwayAlertAt=t;let a={id:makeId(),player:u.id,playerName:u.name,count,at:t,acknowledged:false};state.adminAlerts.unshift(a);write(`antiCheatAlerts/${u.id}/${a.id}`,a).catch(()=>{});if(u.role==='admin')showAlerts()}save()}
window.addEventListener('blur',markAway);window.addEventListener('focus',markReturn);document.addEventListener('visibilitychange',()=>document.hidden?markAway():markReturn());
document.addEventListener('click',e=>{let nav=e.target.closest('[data-page]');if(nav){page=nav.dataset.page;selected=null;render();return}let answer=e.target.closest('[data-answer]');if(answer){selected=Number(answer.dataset.answer);render();return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id,u=me();if(a==='close'){closeModal();return}if(a==='confirm'){let fn=window._arenaConfirm;closeModal();fn?.();return}if(a==='accept'){state.accepted=true;save();closeModal();render();return}if(a==='reality'){state.realitySeen=true;save();closeModal();render();return}if(a==='policy-accept'){log('messages',{kind:'policy reread',user:uid()});toast('Policy acceptance recorded.');return}if(a==='logout'){log('signin',{event:'logout',user:uid()});currentId=null;stopCloud();cloud()?.signOut().catch(()=>{});renderAuth();return}if(a==='reset-email'){let email=$('#login input[name=email]')?.value.trim();if(!email)return toast('Enter your email first.','bad');cloud()?.sendPasswordReset(email).then(()=>toast('Password reset email sent.')).catch(x=>toast(x.message,'bad'));return}if(a==='help'){modal(`<div class="eyebrow">Account help</div><h2>Message the Admin</h2><form id="help-form" class="form"><label>Username<input name="username" required></label><label>Reason<select name="reason"><option>Forgot password</option><option>Banned account appeal</option><option>Other account problem</option></select></label><label>Message<textarea name="message" maxlength="700" required></textarea></label><p class="muted">Your request is sent without signing in. Never send your password.</p><button>Send request</button></form>`);return}if(a==='start-quiz'){startQuiz();return}if(a==='submit-answer'){submitAnswer();return}if(a==='finish-quiz'){quiz=null;page='Home';render();return}if(a==='quit-quiz'){quiz=null;selected=null;page='Play';render();return}if(a==='hint'){hint();return}if(a==='daily'){dailyReward();return}if(a==='rename'){rename();return}if(a==='profile'){profileModal(id);return}if(a==='start-dm'){window.dmTarget=id;page='Inbox';render();return}if(a==='send-chat'){sendChat();return}if(a==='send-dm'){sendDm(id);return}if(a==='challenge'){let to=$('#challenge-target')?.value;if(!to)return toast('No other eligible players.','bad');let c={id:makeId(),from:u.id,to,status:'pending',at:now(),answers:[]};state.challenges.unshift(c);log('messages',{kind:'challenge invite',from:u.id,to});save();write('challenges/'+c.id,c).catch(()=>{});render();return}if(a==='accept'||a==='decline'){let c=state.challenges.find(x=>x.id===id);if(!c)return;c.status=a==='accept'?'accepted':'declined';log('messages',{kind:'challenge '+c.status,challenge:id,player:u.id});save();write('challenges/'+id,c).catch(()=>{});render();return}if(a==='duel'){startDuel(id);return}if(a==='ack-notice'){let n=state.notices.find(x=>x.id===id);if(n){n.acknowledgedBy=n.acknowledgedBy||[];if(!n.acknowledgedBy.includes(u.id))n.acknowledgedBy.push(u.id);n.readBy=n.readBy||[];if(!n.readBy.includes(u.id))n.readBy.push(u.id);write(`noticeReads/${u.id}/${n.id}`,{read:true,acknowledged:true}).catch(()=>{});log('messages',{kind:'notice acknowledged',notice:n.title,user:u.id});render()}return}if(a==='ack-alert'){let x=state.adminAlerts.find(x=>x.id===id);if(x){x.acknowledged=true;x.acknowledgedBy=u.id;write(`antiCheatAlerts/${x.player}/${x.id}`,x).catch(()=>{});closeModal();showAlerts()}return}if(a==='save-mode'){twoStep('Change day mode','Set the shared weekday/weekend question plan?',()=>{state.mode=$('#day-mode').value;write('settings/mode',state.mode).catch(()=>{});log('admin',{action:'day mode changed',mode:state.mode});render()});return}if(a==='publish-notice'){let title=$('#notice-title').value.trim(),body=$('#notice-body').value.trim();if(!title||!body)return toast('Enter a title and notice message.','bad');let n={id:makeId(),title:title.slice(0,100),body:body.slice(0,1000),at:now(),readBy:[],acknowledgedBy:[]};state.notices.unshift(n);write('notices/'+n.id,n).catch(()=>{});log('messages',{kind:'admin notice published',title});render();return}if(a==='role'){let target=byId(id),role=$('#role-'+id).value;if(target.role==='admin'&&role!=='admin'&&state.users.filter(x=>x.role==='admin').length<=1)return toast('Cannot remove the last Admin.','bad');twoStep('Change account role',`Set ${target.username} to ${role}?`,()=>{syncRoleAdmin(id,role);target.role=role;log('admin',{action:'role changed',target:target.username,role});if(role!=='user')toast(`🎉 ${target.name} promoted to ${role}!`);render()});return}if(a==='ban'||a==='suspend'){let target=byId(id),field=a==='ban'?'banned':'suspended',value=!target[field];if(a==='ban'&&target.role==='admin'&&value&&state.users.filter(x=>x.role==='admin'&&!x.banned).length<=1)return toast('Cannot ban the last active Admin.','bad');twoStep(value?'Restrict account':'Restore account',`${value?'Restrict':'Restore'} ${target.username}?`,()=>{target[field]=value;write(`moderation/accounts/${id}`,{banned:!!target.banned,suspended:!!target.suspended,role:target.role}).catch(()=>{});log('admin',{action:a==='ban'?(value?'account banned':'account unbanned'):(value?'account suspended':'account unsuspended'),target:target.username});render()});return}if(a==='remove-account'){let target=byId(id);if(!target||target.id===u.id)return;twoStep('Remove Arena data',`Remove ${target.username}'s Arena data and block access? Their Firebase Auth identity must also be removed in Console.`,()=>removeAccountData(target,u));return}if(a==='resolve-help'){let owner=b.dataset.owner,request=state.supportRequests.find(x=>x.id===id);if(request){request.status='resolved';write(`supportRequests/${owner}/${id}`,request).catch(()=>{});render()}return}if(a==='clear-logs'){twoStep('Clear audit logs','Clear all Arena logs?',clearLogs);return}if(a==='reset-board'){twoStep('Reset leaderboard','Reset points and answer history for every player?',()=>{for(const x of state.users){x.points=0;x.streak=0;x.bestStreak=0;x.answers=[]}for(const x of state.users)write(`scores/${x.id}`,{points:0,streak:0,bestStreak:0,accuracy:0}).catch(()=>{});save();log('admin',{action:'leaderboard reset'});render()});return}if(a==='export-logs'){exportLogs();return}if(a==='logs-mode'){logMode=b.dataset.mode;render();return}if(a==='export-backup'){backup();return}if(a==='import-backup'){$('#backup-file').click();return}if(a==='rename'){rename();return}if(a==='toggle-question'||a==='remove-question'){let q=state.questions.find(x=>x.id===id);if(!q)return;if(a==='remove-question'){state.questions=state.questions.filter(x=>x.id!==id);write('questions/'+id,null).catch(()=>{});log('questions',{event:'removed',questionId:id,actor:u.id})}else{q.active=!q.active;write('questions/'+id,q).catch(()=>{});log('questions',{event:q.active?'resumed':'stopped',questionId:id,actor:u.id})}render();return}if(a==='preview'){let q=state.questions.find(x=>x.id===id);if(q)modal(`<div class="eyebrow">Early preview · ${esc(q.subject)}</div><h2>${esc(q.text)}</h2>${q.options.map((x,i)=>`<div class="item">${i+1}. ${esc(x)} ${i===q.answer?' ✓ Correct':''}</div>`).join('')}<p>Unlock: ${q.releaseAt?new Date(q.releaseAt).toLocaleString():'Immediately'}</p><button data-action="close">Close</button>`);return}if(a==='schedule-question'){let q=state.questions.find(x=>x.id===id);if(q){q.releaseAt=Math.max(now(),q.releaseAt||now())+Number(b.dataset.add);write('questions/'+id,q).catch(()=>{});log('questions',{event:'scheduled/updated',questionId:id,releaseAt:q.releaseAt});render()}return}if(a==='clear-chat'){twoStep('Clear chat','Delete all public chat messages?',()=>{for(const m of state.chat)write('chat/'+m.id,null).catch(()=>{});state.chat=[];render()});return}});
document.addEventListener('submit',async e=>{let f=e.target;if(f.id==='login'||f.id==='signup'){e.preventDefault();let c=cloud();if(!c)return toast('Firebase did not load. Connect to the internet.','bad');let d=new FormData(f),email=String(d.get('email')||'').trim().toLowerCase(),password=String(d.get('password')||'');try{if(f.id==='login'){await c.signIn(email,password);return}let name=String(d.get('name')||'').trim().slice(0,24),username=String(d.get('username')||'').trim().toLowerCase();if(!/^[a-z0-9_]{3,20}$/.test(username))return toast('Username must be 3–20 letters, numbers, or underscores.','bad');if(state.users.some(x=>x.username.toLowerCase()===username))return toast('That username is already in use.','bad');let cred=await c.createAccount(email,password);pendingProfiles[cred.user.uid]={name,username};await c.write(`profiles/${cred.user.uid}`,{displayName:name,username,createdAt:now()});await c.write(`scores/${cred.user.uid}`,{points:0,streak:0,bestStreak:0,accuracy:0});toast('Account created. Welcome to the Arena!')}catch(err){toast(err.message||'Sign-in failed.','bad')}return}if(f.id==='question-form'){e.preventDefault();let d=new FormData(f),options=String(d.get('options')).split('\n').map(x=>x.trim()).filter(Boolean);if(options.length!==4)return toast('Enter exactly four answer options.','bad');let releaseAt=d.get('releaseAt')?new Date(d.get('releaseAt')).getTime():0,q={id:makeId(),subject:d.get('subject'),text:String(d.get('text')).trim(),options,answer:Math.max(0,Math.min(3,Number(d.get('answer'))-1)),explanation:'Review the key clue and try another subject.',active:true,releaseAt};state.questions.push(q);write('questions/'+q.id,q).catch(()=>{});log('questions',{event:'added',questionId:q.id,actor:uid()});toast('Question added.');render();return}if(f.id==='help-form'){e.preventDefault();let c=cloud(),d=new FormData(f);if(!c)return toast('Connect to the internet before sending account help.','bad');try{let anon=await c.signInAnonymously(),who=anon.user.uid,req={id:makeId(),userId:who,accountId:who,username:String(d.get('username')).slice(0,20),reason:d.get('reason'),message:String(d.get('message')).slice(0,700),at:now(),status:'open'};await c.write(`supportRequests/${who}/${req.id}`,req);await c.signOut();modal(`<h2>Message sent</h2><p>Your request is visible to the Admin.</p><button data-action="close">Close</button>`)}catch(err){toast(err.message||'Could not send request.','bad')}return}if(f.id==='delete-self-form'){e.preventDefault();let authUser=cloud()?.auth.currentUser,password=new FormData(f).get('password');try{let cred=firebase.auth.EmailAuthProvider.credential(authUser.email,password);await authUser.reauthenticateWithCredential(cred);await removeAccountData(me(),me(),true)}catch(err){toast(err.message||'Password confirmation failed.','bad')}return}});
document.addEventListener('change',e=>{if(e.target.id==='dm-target'){window.dmTarget=e.target.value;render()}if(e.target.id==='log-filter'){filter=e.target.value;render()}if(e.target.id==='backup-file'&&e.target.files?.[0])importBackup(e.target.files[0]);if(e.target.id==='log-search'){let pos=e.target.selectionStart;render();$('#log-search')?.focus();$('#log-search')?.setSelectionRange(pos,pos)}});
document.addEventListener('input',e=>{if(e.target.id==='log-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('.log-entry').forEach(x=>x.classList.toggle('hidden',!x.textContent.toLowerCase().includes(q)))}});
function dailyReward(){let u=me(),day=today();if(u.lastDay===day)return toast('Daily reward already claimed.');u.lastDay=day;u.daily=(u.daily||0)+1;if(u.daily%3===0){u.freezes=(u.freezes||0)+1;toast('Daily reward: streak freeze ❄️')}else if(u.daily%2===0){u.shields=(u.shields||0)+1;toast('Daily reward: streak shield 🛡️')}else{u.doubleNext=true;toast('Daily reward: next correct answer is 2× points!')}save();updatePrivateCloud(u);render()}
function rename(){let u=me(),name=$('#new-name')?.value.trim();if(!name)return toast('Enter a display name.','bad');if(u.nameChanged&&now()-u.nameChanged<5*86400000)return toast('Display names can change once every 5 days.','bad');u.name=name.slice(0,24);u.nameChanged=now();save();updateProfileCloud(u);log('admin',{action:'display name changed',actor:u.id,name:u.name});render()}
async function removeAccountData(target,actor,self=false){let c=cloud(),uidTarget=target.id;if(!c)return;if(self){let paths=[`profiles/${uidTarget}`,`scores/${uidTarget}`,`playerData/${uidTarget}`,`admins/${uidTarget}`,`dms/${uidTarget}`,`supportRequests/${uidTarget}`,`noticeReads/${uidTarget}`,`logs/${uidTarget}`];for(const path of paths)c.database.ref(path).remove().catch(()=>{});for(const m of state.dms.filter(x=>x.from===uidTarget||x.to===uidTarget)){c.database.ref(`dms/${m.from}/${m.id}`).remove().catch(()=>{});c.database.ref(`dms/${m.to}/${m.id}`).remove().catch(()=>{})}for(const m of state.chat.filter(x=>x.from===uidTarget))c.database.ref(`chat/${m.id}`).remove().catch(()=>{});for(const ch of state.challenges.filter(x=>x.from===uidTarget||x.to===uidTarget))c.database.ref(`challenges/${ch.id}`).remove().catch(()=>{});await c.auth.currentUser.delete();return}await c.database.ref(`moderation/accounts/${uidTarget}`).set({banned:true,suspended:true,deleted:true,role:'user',at:now()});await c.database.ref(`profiles/${uidTarget}`).remove();await c.database.ref(`scores/${uidTarget}`).remove();await c.database.ref(`playerData/${uidTarget}`).remove();state.users=state.users.filter(x=>x.id!==uidTarget);log('admin',{action:'account blocked and Arena profile removed',target:target.username,actor:actor.id});toast('Arena profile removed and access blocked. Remove their Firebase Auth user from Console to delete the sign-in too.');render()}
function tick(){document.querySelectorAll('[data-unlock]').forEach(el=>{let ms=Number(el.dataset.unlock)-now();if(ms<=0){el.textContent='unlocked';setTimeout(render,250)}else{let n=Math.ceil(ms/1000);el.textContent=`${Math.floor(n/3600)}h ${String(Math.floor(n%3600/60)).padStart(2,'0')}m ${String(n%60).padStart(2,'0')}s`}});if($('#q-timer')&&quiz)$('#q-timer').textContent=Rules.seconds(now()-quiz.started)+'s'}setInterval(tick,1000);
async function init(){if(!state.accepted){render();return}if(!cloud()){renderAuth();toast('Firebase SDK is unavailable. Connect to the internet and reload.','bad');return}cloud().onAuth(async fb=>{if(!fb){currentId=null;stopCloud();render();return}await activate(fb)})}init();
})();
